use vstd::prelude::*;

verus! {

    /// `solve` simply returns a copy of the input vector `t`.
    fn solve(t: Vec<char>) -> Vec<char>
        ensures
            // the “view” of the result vector is exactly the same as
            // the view of the input vector
            result@ == t@,
    {
        let n = t.len();
        let mut out = Vec::with_capacity(n);
        let mut i = 0;

        // copy one element at a time
        while i < n
            invariant
                // we never over‐run the input
                i <= n,
                // the output vector has grown exactly to length `i`
                out.len() == i,
                // and for every index < i, out[k] == t[k]
                forall |k: nat| k < i ==> out@ [k] == t@ [k],
            decreases n - i,
        {
            out.push(t[i]);
            i = i + 1;
        }

        out
    }

} // end of `verus!`

